sys_ws_operation.operation_script:
(function process(request, response) {
    var property = request.body.data.sysparm_property; // Property name
    var suggestedValue = request.body.data.sysparm_suggested_value; // Suggested value

    // Validate input
    if (!property || !suggestedValue) {
        response.setBody({
            status: 'failure',
            message: 'Invalid input. Property name or suggested value is missing.'
        });
        return;
    }

    try {
        // Query the sys_properties table
        var gr = new GlideRecord('sys_properties');
        if (gr.get('name', property)) {
            gr.setValue('value', suggestedValue); // Update property value
            gr.update();

            response.setBody({
                status: 'success',
               // message: `Property ${property} updated successfully.`
            });
        } else {
            response.setBody({
                status: 'failure',
               // message: `Property ${property} not found.`
            });
        }
    } catch (error) {
        response.setBody({
            status: 'failure',
         //   message: `Error updating property: ${error.message}`
        });
    }
})(request, response);
